import {sum,day,groupRates,signalRegister,profileData,compareGroups,costSensitivity,planningInputs,governanceGates,actionBlockers,suggestClassification,comparableEffect,operatingMetrics,ledgerSummary} from './intelligence.js';
import {deriveCost,deriveEffectiveness} from './analysis-core.js';

export const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=x=>x===null||x===undefined||!Number.isFinite(Number(x))?'—':Number(x).toLocaleString('en-US',{maximumFractionDigits:1});
const pc=x=>x==null?'—':n(x)+'%';
const usd=x=>x==null?'—':'$'+Number(x).toLocaleString('en-US',{maximumFractionDigits:0});
const pill=(text,tone='neutral')=>`<span class="badge ${tone}">${e(text)}</span>`;
const button=(text,view)=>`<button class="text-button" data-view="${view}">${e(text)} <span>↗</span></button>`;
const empty=text=>`<div class="chart-empty">${e(text)}</div>`;
const panel=(title,desc,body,action='')=>`<section class="panel"><div class="panel-title"><div><h2>${e(title)}</h2><p>${e(desc)}</p></div>${action}</div>${body}</section>`;
const stat=(label,value,note,tone='')=>`<div class="stat ${tone}"><span>${e(label)}</span><strong>${e(value)}</strong><small>${e(note)}</small></div>`;
const field=(label,name,value,type='text',extra='')=>`<label class="field"><span>${e(label)}</span><input name="${name}" type="${type}" value="${e(value??'')}" ${extra}></label>`;
const select=(label,name,values,current)=>`<label class="field"><span>${e(label)}</span><select name="${name}">${values.map(v=>`<option ${v===current?'selected':''}>${e(v)}</option>`).join('')}</select></label>`;
const textArea=(label,name,value,extra='')=>`<label class="field full"><span>${e(label)}</span><textarea name="${name}" ${extra}>${e(value)}</textarea></label>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
export const NAV=[['overview','Overview','Executive workspace'],['studio','Analysis studio',''],['visuals','Visual library',''],['trace','Traceability','Quality intelligence'],['quality','Quality signals',''],['investigate','Investigation',''],['customers','Customer feedback',''],['containment','Containment','Decision & recovery'],['recovery','Recovery planner',''],['cost','Cost intelligence',''],['capa','CAPA command','Execution & assurance'],['learning','Effectiveness',''],['data','Data workspace','Workspace']];
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',trace:'M5 4h14v5H5z M5 15h5v5H5z M15 15h5v5h-5z M12 9v3 M7 15v-3h11v3',quality:'M3 18l5-7 4 3 5-10 4 4',investigate:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14 M15 15l6 6',customers:'M4 4h16v13H9l-5 4z M8 8h8 M8 12h5',containment:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M9 12l2 2 4-4',recovery:'M4 4v16h17 M8 7h10 M8 12h7 M8 17h12',cost:'M12 2v20 M17 6H9a3 3 0 0 0 0 6h6a3 3 0 0 1 0 6H6',capa:'M5 4h14v17H5z M9 2h6v4H9z M8 11l2 2 5-5 M8 17h8',learning:'M4 12a8 8 0 1 1 2 6 M4 18v-6h6 M12 8v5l3 2',data:'M3 6c0-4 18-4 18 0s-18 4-18 0v12c0 4 18 4 18 0V6 M3 12c0 4 18 4 18 0'};
function icon(id){return `<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[id]||paths.overview}"/></svg>`;}
export function shellPage(db,view,page,activeFocus){
  return `<div class="app-layout"><aside class="app-sidebar" id="sidebar"><a class="wordmark" href="#overview"><span class="logo-symbol">${icon('trace')}</span><span>Factory<span>Sphere</span></span></a><div class="workspace-label">QUALITY OPERATIONS</div><nav aria-label="Primary">${NAV.map(([id,label,group])=>`${group?`<div class="nav-group">${group}</div>`:''}<button data-view="${id}" class="nav-item ${id===view?'active':''}" ${id===view?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${id==='capa'&&db.actions.some(a=>a.status!=='Done')?`<b>${db.actions.filter(a=>a.status!=='Done').length}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><span class="online-dot"></span><div><strong>Browser workspace</strong><small>Data processed on this device</small></div></div></aside><div class="app-main"><header class="app-topbar"><div class="breadcrumb">Workspace <span>/</span> <strong>${e(NAV.find(n=>n[0]===view)?.[1]||view)}</strong></div><div class="top-actions"><span id="save-indicator" class="save-indicator" role="status">Browser data</span><span class="dataset-indicator"><i></i>${e(db.incident.id)}</span><button class="btn" data-action="report-html">Export report</button><button class="btn primary" data-action="upload">+ Import data</button><span class="user-avatar">FS</span></div></header><main class="app-content">${page}</main><footer class="app-footer"><span>FactorySphere <b>2.0</b> · Decision intelligence</span><span>${e(activeFocus)} · ${e(db.sourceName)} · USD</span></footer></div></div>`;
}
function chartFrame(label,body,height=238){return `<svg class="analytics-chart" role="img" aria-label="${e(label)}" viewBox="0 0 640 ${height}"><title>${e(label)}</title>${body}</svg>`;}
export function controlChart(control){
  if(!control.points.length)return empty('Dated inspection records are required for statistical monitoring.');
  const {points,mean}=control,max=Math.max(5,...points.map(p=>Math.max(p.high,p.rate)))*1.12,x=i=>48+i*560/Math.max(1,points.length-1),y=v=>180-v/max*146;
  let body='';
  for(let i=0;i<=4;i++){const v=max*i/4;body+=`<line x1="48" y1="${y(v)}" x2="608" y2="${y(v)}" class="chart-grid"/><text x="38" y="${y(v)+4}" text-anchor="end">${v.toFixed(1)}%</text>`;}
  body+=`<polygon class="control-band" points="${points.map((p,i)=>`${x(i)},${y(p.high)}`).join(' ')} ${points.map((p,i)=>`${x(i)},${y(p.low)}`).reverse().join(' ')}"/><line x1="48" y1="${y(mean)}" x2="608" y2="${y(mean)}" class="chart-mean"/>`;
  body+=`<polyline class="chart-limit" points="${points.map((p,i)=>`${x(i)},${y(p.high)}`).join(' ')}"/><polyline class="chart-series" points="${points.map((p,i)=>`${x(i)},${y(p.rate)}`).join(' ')}"/>`;
  points.forEach((p,i)=>{body+=`<circle cx="${x(i)}" cy="${y(p.rate)}" r="${p.signal?5:4}" class="${p.signal?'chart-alert':'chart-point'}"><title>${e(p.id)} · ${e(p.date)} · ${p.defects}/${p.sample} · ${pc(p.rate)} · limits ${pc(p.low)}–${pc(p.high)}</title></circle>`;if(i===0||i===points.length-1||i%Math.max(1,Math.ceil(points.length/5))===0)body+=`<text x="${x(i)}" y="207" text-anchor="middle">${e(p.date.slice(5))}</text>`;});
  return chartFrame('Defective unit rate with sample-adjusted three-sigma control limits',body)+`<div class="chart-legend"><span><i class="key teal"></i>Observed rate</span><span><i class="key band"></i>3σ limits</span><span>Mean ${pc(mean)}</span></div><p class="chart-note">${control.provisional?'Provisional: fewer than 20 comparable subgroups. ':'Limits estimated from displayed history. '}${points.some(p=>p.limited)?'Small expected counts weaken the normal approximation. ':''}Control limits are not acceptance thresholds. Hover points for evidence.</p>`;
}
function bars(items,format=pc,attr=''){
  if(!items.length)return empty('No matching evidence in the active file.');
  const max=Math.max(1,...items.map(i=>i.value));
  return `<div class="analytical-bars">${items.map(i=>`<${attr?'button':'div'} class="analytical-bar" ${attr?`${attr}="${e(i.label)}"`:''}><span class="bar-name">${e(i.label)}</span><div class="bar-track"><i style="width:${Math.max(0,i.value/max*100)}%"></i></div><b>${e(format(i.value))}</b><small>${e(i.note||'')}</small></${attr?'button':'div'}>`).join('')}</div>`;
}
function exposureComposition(a){
  const groups=['Confirmed','Precautionary','Separate signal','Unrelated','Reference'].map((label,i)=>{const rows=a.exposure.filter(b=>b.scope===label);return {label,count:rows.length,stock:sum(rows,'inventory'),missing:rows.some(b=>b.inventory===null),tone:['danger','warning','info','neutral','neutral'][i]}}).filter(g=>g.count);
  return `<div class="exposure-total"><strong>${a.exposure.length}</strong><span>batches assessed<br>for ${e(a.focus)}</span></div><div class="scope-strip">${groups.map(g=>`<span class="${g.tone}" style="width:${g.count/a.exposure.length*100}%" title="${e(g.label)}: ${g.count}"></span>`).join('')}</div><div class="scope-list">${groups.map(g=>`<div>${pill(g.label,g.tone)}<b>${g.count}</b><span>${n(g.stock)} stock${g.missing?' + unknown':''}</span></div>`).join('')}</div>`;
}
function focusControls(db,a,state){return `<div class="analysis-toolbar"><span class="toolbar-label">Analysis scope</span><label>Defect<select id="focus-defect">${['Auto',...a.defects.map(d=>d.type)].map(v=>`<option value="${e(v)}" ${v===state.focusDefect?'selected':''}>${e(v==='Auto'?a.focus+' (auto)':v)}</option>`).join('')}</select></label><label>Reference batch<select id="focus-batch">${['Auto',...db.batches.map(b=>b.id)].map(v=>`<option value="${e(v)}" ${v===state.referenceBatch?'selected':''}>${e(v==='Auto'?a.reference.id+' (auto)':v)}</option>`).join('')}</select></label><label>Factory<select id="factory-filter">${['All',...new Set(db.batches.map(b=>b.factory))].map(v=>`<option ${v===state.factoryFilter?'selected':''}>${e(v)}</option>`).join('')}</select></label><label>Exposure<select id="scope-filter">${['All','Confirmed','Precautionary','Separate signal','Reference','Unrelated'].map(v=>`<option ${v===state.scopeFilter?'selected':''}>${e(v)}</option>`).join('')}</select></label><button class="text-button" data-action="clear-filters">Reset</button></div>`;}
export function overviewPage(db,a,plans,state){
  const signals=signalRegister(db,a),p=profileData(db),economics=deriveCost(db,a),plan=plans.find(p=>p.name===state.selectedRecovery)||plans[0];
  const visible=a.exposure.filter(b=>(state.factoryFilter==='All'||b.factory===state.factoryFilter)&&(state.scopeFilter==='All'||b.scope===state.scopeFilter));
  const ids=new Set(visible.map(b=>b.id)),rows=a.focusRows.filter(i=>ids.has(i.batch)),sample=sum(rows,'sample'),defects=sum(rows,'defects'),confirmed=visible.filter(b=>b.scope==='Confirmed');
  const known=(list,key)=>list.length?list.every(b=>b[key]!==null)?sum(list,key):null:0;
  const overdue=db.actions.filter(x=>x.status!=='Done'&&x.due&&x.due<day());
  const filtered=state.factoryFilter!=='All'||state.scopeFilter!=='All';
  const headline=a.confirmed.length?`${n(a.confirmedStock)} stock units need a recovery decision`:`${a.precautionary.length} precautionary batch${a.precautionary.length===1?' needs':'es need'} verification`;
  let html=`<div class="executive-heading"><div><div class="eyebrow">OPERATIONS INTELLIGENCE ${db.groundTruth||db.sourceName==='enterprise-demonstration.json'?'<span class="synthetic-label">Synthetic demonstration</span>':''}</div><h1>Quality, connected.</h1><p>Understand the exposure. Choose the recovery. Verify the outcome.</p></div><div class="date-context"><strong>${e(day())}</strong><span>${e(p.dates[0]||'Undated')} — ${e(p.dates[1]||'Undated')} · inspection coverage</span></div></div>`;
  html+=focusControls(db,a,state);
  html+=`<div class="decision-banner"><div><span class="decision-label">${e(db.incident.id)} / ${e(a.focus)}</span><h2>${e(headline)}</h2><p>${a.confirmed.length} confirmed · ${a.precautionary.length} precautionary · ${n(a.confirmedShipped)} known shipped units. ${a.warnings.length?'Data gaps require review before release.':'Scope based on linked inspection and complaint evidence.'}</p></div><button class="btn light" data-view="${a.confirmed.length?'recovery':'quality'}">${a.confirmed.length?'Evaluate recovery':'Review evidence'} →</button></div>`;
  html+=`<div class="stat-grid">${stat('Observed defective rate',pc(sample?defects/sample*100:null),`${n(defects)} / ${n(sample)} inspections · ${filtered?'filtered':'selected defect'}`,'teal')}${stat('Confirmed stock exposure',n(known(confirmed,'inventory')),'Units · '+confirmed.length+' displayed batches','danger')}${stat('Known quality cost',usd(economics.known),`${a.costCoverage}/4 categories · entire dataset`)}${stat('Overdue actions',n(overdue.length),`${db.actions.filter(x=>x.status!=='Done').length} open · entire incident`,overdue.length?'danger':'')}</div>`;
  html+=`<div class="analytics-grid main-split">${panel('Is the process stable?',signals.cohort+(filtered?' · independent of table filters':''),controlChart(signals.control),button('Quality signals','quality'))}${panel('Keep confirmed and precautionary scope distinct','Batch composition · entire selected-defect analysis',exposureComposition(a),button('Trace evidence','trace'))}</div>`;
  const pareto=[...a.defects].sort((x,y)=>y.defects-x.defects),total=pareto.reduce((s,d)=>s+d.defects,0);let cumulative=0;
  html+=`<div class="analytics-grid equal-split">${panel('Focus improvement where defects concentrate','Counts by defect; cumulative share of recorded defects',bars(pareto.map(d=>{cumulative+=d.defects;return {label:d.type,value:d.defects,note:total?pc(cumulative/total*100)+' cumulative':'No observed defects'}}),n,'data-focus-type'))}${panel('Decisions requiring attention','Prioritized from the active file',`<div class="decision-list">${[[signals.signals.length+' quality signals','Inspect evidence and verify emerging patterns','quality'],[plan?`${n(plan.totalDays)} working days to recover`:'Recovery needs confirmed stock',plan?`${usd(plan.cost)} incremental · ${plan.complete} full completion`:'Complete inventory and confirm scope before scheduling','recovery'],[`${overdue.length} overdue commitments`,db.incident.closed?'Case closed':'Resolve missing evidence and dependencies','capa']].map(([title,desc,view])=>`<button data-view="${view}"><span class="decision-icon">${icon(view)}</span><span><strong>${e(title)}</strong><small>${e(desc)}</small></span><b>↗</b></button>`).join('')}</div>`)}</div>`;
  html+=panel('Exposure register','Select a batch to follow its genealogy · '+visible.length+' matching batches',table(['Batch / style','Factory / line','Classification','Inventory','Shipped','Evidence / rationale'],visible.map(b=>[`<button class="text-button" data-view="trace" data-batch="${e(b.id)}">${e(b.id)} ↗</button><small class="cell-detail">${e(b.sku||'Unknown style')}</small>`,e(b.factory)+'<small class="cell-detail">'+e(b.line||'Line not supplied')+'</small>',pill(b.scope,b.scope==='Confirmed'?'danger':b.scope==='Precautionary'?'warning':'neutral'),n(b.inventory),n(b.shipped),e(b.reason)])))+(visible.length?'':empty('No batches match these display filters.'));
  html+=`<div class="source-footer"><span><i class="online-dot"></i> ${e(db.sourceName)} · ${db.inspections.length} inspection records · loaded ${e(new Date(db.loadedAt).toLocaleString('en-GB',{timeZone:'Asia/Dhaka'}))}</span>${button(p.unreviewed+' screening records · inspect data quality','data')}</div>`;
  return html;
}
export function intelligencePanels(view,db,a,plans,state){
  const rows=a.focusRows;
  if(view==='quality'){
    const s=signalRegister(db,a),locations=groupRates(db,rows,'location');
    return operatingPanels(db,a)+`<div class="analytics-grid main-split">${panel('Statistical process monitoring',s.cohort,controlChart(s.control))}${panel('Where are failures observed?','Defective units / inspected units by garment location',bars(locations.map(g=>({label:g.label,value:g.rate,note:`${g.defects}/${g.sample} · 95% interval ${pc(g.ci.low)}–${pc(g.ci.high)}`}))))}</div>`+panel('Explainable signal register','Associations require human verification; no automatic root-cause declaration',s.signals.length?table(['Signal','Location / batch','Evidence','Uncertainty','Verification step'],s.signals.map(s=>[pill(s.severity,s.severity==='High'||s.severity==='Critical'?'danger':'warning')+'<strong class="cell-detail">'+e(s.title)+'</strong>',e(s.where),e(s.records.join(', '))+'<small class="cell-detail">'+e(s.detail)+'</small>',e(s.uncertainty),e(s.next)])):empty('No rules triggered for this evidence set. This does not establish process stability.'));
  }
  if(view==='trace'){
    const b=db.batches.find(b=>b.id===state.selectedBatch)||a.reference;
    const tiers=[['Material inputs',[b.fabric,b.thread,b.trim]],['Production',[b.cutting,b.line,b.machine,b.team]],['Finished goods',[b.finishing,b.packing,b.id]],['Distribution',[...db.shipments.filter(s=>s.batch===b.id).map(s=>s.id),...db.complaints.filter(c=>c.batch===b.id).map(c=>c.id)]]];
    return panel('From input to customer signal','Selected batch '+b.id+' · supplied identifiers only',`<div class="network-map">${tiers.map(([title,nodes],i)=>`<div class="network-tier"><h3>${e(title)}</h3>${nodes.filter(Boolean).map(x=>`<div class="network-node ${x===b.id?'selected':''}">${e(x)}</div>`).join('')||'<div class="network-node missing">Not supplied</div>'}</div>${i<3?'<span class="network-arrow">→</span>':''}`).join('')}</div><p class="chart-note">Links show shared batch associations, not evidence that all linked products are defective.</p>`);
  }
  if(view==='investigate'){
    const tests=['machine','fabric','line','shift'].map(f=>({field:f,result:compareGroups(db,rows,f)}));
    const w=db.workspace||{},hyp=w.hypotheses||[];
    return panel('Test associations before confirming a cause','Exploratory comparisons · 95% approximate difference intervals; no adjustment for multiple comparisons',table(['Factor','Higher-rate group','Control group','Difference','Interpretation'],tests.map(({field,result:r})=>[e(field),r?e(r.high.label)+' · '+pc(r.high.rate):'—',r?e(r.control.label)+' · '+pc(r.control.rate):'—',r?`${n(r.difference)} pp<small class="cell-detail">${n(r.low)} to ${n(r.upper)} pp</small>`:'—',r?e(r.adequate?r.conclusion:'Sparse counts: insufficient evidence for normal inference'):'At least two groups required'])))+
    panel('Hypothesis & fishbone register','Machine · method · material · people · measurement · environment · design',`<div class="fishbone-grid">${['Machine','Method','Material','People','Measurement','Environment','Design'].map(c=>`<section><h3>${e(c)}</h3>${hyp.filter(h=>h.category===c).map(h=>`<p><strong>${e(h.hypothesis)}</strong><small>${e(h.status)} · ${e(h.reviewer)}<br>${e(h.evidence||'Evidence pending')}</small></p>`).join('')||'<p class="muted">No hypothesis recorded</p>'}</section>`).join('')}</div><details><summary>Add a testable hypothesis</summary><form id="hypothesis-form" class="form-grid">${select('Category','category',['Machine','Method','Material','People','Measurement','Environment','Design'],'Machine')}${field('Reviewer','reviewer','','text','required')}${textArea('Hypothesis','hypothesis','','required')}${textArea('Verification test / control','test','','required')}${field('Evidence IDs','evidence','')}${select('Finding','status',['Untested','Supported','Rejected','Inconclusive'],'Untested')}<button class="btn primary">Save hypothesis</button></form></details>`)+
    panel('5 Whys · causal chain','Explain each link; the cause confirmation still requires supporting evidence',`<form id="whys-form" class="why-chain">${Array.from({length:5},(_,i)=>`<label><b>${String(i+1).padStart(2,'0')}</b><span>Why ${i+1}?<textarea name="why${i}" rows="2">${e(w.whys?.[i]||'')}</textarea></span></label>`).join('')}<button class="btn primary">Save causal chain</button></form>`);
  }
  if(view==='recovery'){
    const chosen=plans.find(o=>o.name===state.selectedRecovery)||plans[0],p=planningInputs(db);
    const assumptions=[['shiftHours','Hours / shift',1,24],['workingDays','Workdays / week (5, 6, 7)',5,7],['reinspectionRate','Reinspection units / person-hour',1,null],['packingRate','Packing units / day',1,null],['replacementRate','Replacement units / day',1,null],['materialLeadDays','Material lead time (workdays)',0,null],['approvalDays','Approval lead time (workdays)',0,null],['skillAvailability','Skilled capacity %',1,100],['machineAvailability','Machine availability %',1,100],['samplePercent','Related-stock sample %',1,100],['priorityPercent','Priority shipment %',1,100],['inspectionCost','Inspection / reinspection $ per hour',0,null],['reworkCost','Rework $ per unit',0,null],['replacementCost','Replacement $ per unit',0,null],['delayCost','Delay $ per calendar day',0,null],['holdingCost','Holding $ per unit-day',0,null],['falseNegative','False-negative assumption %',0,100],['falsePositive','False-positive assumption %',0,100],['handlingRisk','Handling damage assumption %',0,100],['alternateRate','Approved alternate line units / day',1,null],['transferDays','Transfer lead time (workdays)',0,null],['transferCost','Transfer cost USD',0,null],['scrapCost','Scrap disposal $ per unit',0,null]];
    let html=panel('Resource and commercial constraints','Edit assumptions to recompute every scenario and report',`<details><summary>Advanced planning assumptions · ${p.workingDays}-day calendar, ${p.shiftHours}-hour shifts</summary><form id="planning-form" class="form-grid three">${assumptions.map(([k,l,min,max])=>field(l,k,p[k],'number',`required min="${min}" ${max!==null?'max="'+max+'"':''} step="${k==='workingDays'?'1':'any'}"`)).join('')}<button class="btn primary">Apply constraints</button></form></details>`);
    if(!chosen)return html;
    const max=Math.max(1,...plans.map(o=>o.cost));
    html+=`<div class="analytics-grid equal-split">${panel('Recovery cost versus completion','Select a strategy; costs include inspection, repair, holding and delay',`<div class="tradeoff-list">${plans.map((o,i)=>`<button data-plan="${e(o.name)}" class="tradeoff ${o.name===chosen.name?'selected':''}"><span class="strategy-number">${i+1}</span><span><strong>${e(o.name)}</strong><small>${o.complete} · ${o.delay===null?'cut-off unknown':o.delay+' calendar days late'}</small><i class="cost-track"><b style="width:${o.cost/max*100}%"></b></i></span><strong>${usd(o.cost)}</strong></button>`).join('')}</div>`)}${panel('Selected plan · capacity-constrained sequence',chosen.name,`<div class="gantt">${chosen.stages.map(s=>`<div class="gantt-row"><span>${e(s.name)}<small>${e(s.resource)}</small></span><div><i style="margin-left:${s.start/chosen.totalDays*100}%;width:${s.duration/chosen.totalDays*100}%" title="${e(s.startDate)} → ${e(s.endDate)}; ${n(s.duration)} workdays"></i></div><b>${n(s.duration)}d</b></div>`).join('')}</div><p class="chart-note">Sequential dependencies prevent overlap of shared inspectors. ${e(chosen.assumptions)}</p>`)}</div>`;
    html+=panel('Release risk and inspection burden','Modelled risk, not observed outcome',table(['Strategy','Uninspected related stock','Expected missed in inspected stock','Expected false holds','Handling damage exposure'],plans.map(o=>[e(o.name),n(o.untestedRelated),n(o.expectedMissed),n(o.expectedFalseHold),n(o.handlingUnits)]))+'<p class="chart-note">Expected quantities use the confirmed-scope observed defect rate and your sensitivity assumptions. Sampling related stock does not authorize its release. No statistical acceptance sampling claim is made.</p>');
    return html;
  }
  if(view==='cost'){
    const s=costSensitivity(db,a),economics=deriveCost(db,a),count=db.workspace?.economics?.incidentsPerYear,annual=count>0&&economics.avoided!==null?count*economics.avoided:null,prevention=Object.fromEntries(a.costRows).Prevention,payback=annual>0&&prevention!==null?prevention/annual*12:null,max=Math.max(1,...s.points.map(p=>Math.abs(p.net)));
    let chart=empty('Supply both failure costs, prevention investment and reduction assumptions to evaluate sensitivity.');
    if(s.points.length){const x=v=>48+v/100*560,y=v=>116-v/max*85;chart=chartFrame('Expected net prevention value by recurrence probability',`<line x1="48" y1="116" x2="608" y2="116" class="chart-mean"/><text x="46" y="26">Net value (USD)</text><text x="42" y="120" text-anchor="end">$0</text><polyline class="chart-series" points="${s.points.map(p=>`${x(p.probability)},${y(p.net)}`).join(' ')}"/>${s.points.map(p=>`<circle class="${p.net<0?'chart-alert':'chart-point'}" cx="${x(p.probability)}" cy="${y(p.net)}" r="4"><title>${p.probability}% recurrence: ${usd(p.net)} net</title></circle>${p.probability%20===0?`<text x="${x(p.probability)}" y="225" text-anchor="middle">${p.probability}%</text>`:''}`).join('')}`,250)+`<p class="chart-note">Recurrence probability across one comparable future incident. Break-even ${pc(s.breakEven)}${s.breakEven>100?' — outside feasible probability range':''}. This is not a time-based payback forecast.</p>`;}
    return costLedgerPanel(db)+panel('Commercial decision horizon','Payback uses your stated frequency of comparable future incidents',`<div class="stat-grid compact">${stat('Strict COPQ',usd(s.failure),'Internal + external failure')}${stat('COPQ / acceptable garment',economics.copqPerAccepted===null?'—':'$'+economics.copqPerAccepted.toFixed(2),'Failure costs / accepted units')}${stat('Expected avoided loss / year',usd(annual),'Frequency × expected avoided loss')}${stat('Payback period',payback===null?'—':n(payback)+' months','Prevention investment / monthly avoided loss')}</div><form id="economics-form" class="form-grid">${field('Comparable incidents per year','incidentsPerYear',count,'number','min="0.01" step="any"')}<button class="btn primary">Update horizon</button></form><p class="chart-note">Frequency is an explicit assumption; historical cost is not automatically a recurring annual loss.</p>`)+`<div class="analytics-grid equal-split">${panel('Cost burden by category','Known amounts only · USD',bars(a.costRows.filter(([,v])=>v!==null).map(([label,value])=>({label,value})),usd)+`<div class="financial-total"><span>Recorded quality cost</span><b>${usd(economics.known)}</b></div><p class="chart-note">Prevention and appraisal are cost of quality. Internal + external failure (${usd(s.failure)}) are strict COPQ. Total quality cost includes all four categories.</p>`)}${panel('When does prevention pay for itself?','Sensitivity holds failure cost and reduction constant',chart)}</div>`+panel('Intervention trade-offs','Cost, time, effectiveness, people and environmental effects from supplied options',table(['Intervention','Cost / time','Reduction / confidence','Delivery','Worker / safety','Sustainability','Standardization'],db.interventions.map(o=>[e(o.name),usd(o.cost)+' / '+n(o.days)+'d',pc(o.reduction)+' / '+pc(o.confidence),e(o.delivery||'Unknown'),e(o.safety||'Not supplied'),e(o.sustainability||'Not supplied'),e(o.standardize||'Unknown')]))+`<details><summary>Add an intervention for comparison</summary><form id="intervention-form" class="form-grid">${field('Intervention','name','','text','required')}${field('Implementation cost USD','cost','','number','min="0" step="any" required')}${field('Days to implement','days','','number','min="0" step="any" required')}${field('Expected reduction %','reduction','','number','min="0" max="100" step="any" required')}${field('Confidence % (stated estimate)','confidence','','number','min="0" max="100" step="any" required')}${field('Factory resources','resources','','text','required')}${field('Delivery effect','delivery','')}${field('Worker and safety implications','safety','','text','required')}${field('Sustainability consequences','sustainability','','text','required')}${field('Ease of standardization','standardize','')}<button class="btn primary">Add alternative</button></form></details>`);
  }
  if(view==='capa'){
    const w=db.workspace||{},g=w.governance||{};
    return panel('Case progression','Progression reflects evidence; closing remains gated',`<div class="lifecycle">${[['Register',true],['Contain',db.incident.hold||db.incident.shipmentBlock],['Investigate',db.incident.causeConfirmed],['Approve',db.incident.approval&&g.approvalEvidence],['Implement',db.actions.some(a=>a.type==='Corrective'&&a.status==='Done')],['Verify',db.incident.verification.d90],['Close',db.incident.closed]].map(([label,done],i)=>`<div class="${done?'complete':''}"><span>${done?'✓':i+1}</span><strong>${label}</strong></div>`).join('')}</div>`)+
    panel('Cross-functional accountability','R = action owner · A = accountable approver · C = consulted · I = informed',table(['Action / dependency','R','A','C','I','Verification / escalation'],db.actions.map(x=>[e(x.id)+'<small class="cell-detail">'+e(x.dependsOn||'No dependency')+'</small>',e(x.owner||'Missing'),e(x.accountable||'Missing'),e(x.consulted||'—'),e(x.informed||'—'),e(x.verifier||'Missing')+'<small class="cell-detail">'+e(actionBlockers(db,x).length?'Blocked by '+actionBlockers(db,x).join(', '):x.due&&x.due<day()&&x.status!=='Done'?'Overdue · escalate to accountable owner':'No dependency block')+'</small>']))+`<details><summary>Assign RACI and action dependencies</summary><form id="raci-form" class="form-grid">${select('Action ID','id',db.actions.map(a=>a.id),db.actions[0]?.id)}${field('Accountable approver (one person)','accountable','','text','required')}${field('Consulted','consulted','')}${field('Informed','informed','')}${field('Verification owner','verifier','','text','required')}${field('Depends on action IDs (comma separated)','dependsOn','')}<button class="btn primary">Assign responsibilities</button></form></details>`)+
    panel('Approval and independent review','Named acknowledgements are local records; they are not authenticated signatures',`<form id="governance-form" class="form-grid">${field('Management approver','approver',g.approver)}${field('Approval evidence / decision reference','approvalEvidence',g.approvalEvidence)}${field('Approval date','approvalDate',g.approvalDate,'date',`max="${day()}"`)}${field('Independent effectiveness reviewer','verifier',g.verifier)}${field('Comparable cohort / complexity review evidence','comparisonEvidence',g.comparisonEvidence)}${select('Final verification decision','verificationDecision',['','Accepted','Further evidence required'],g.verificationDecision||'')}<button class="btn primary">Save governance record</button></form><div class="gate-list">${governanceGates(db).map(([label,pass])=>`<div>${pill(pass?'Complete':'Missing',pass?'success':'warning')} ${e(label)}</div>`).join('')}</div>`);
  }
  if(view==='learning'){
    const effect=deriveEffectiveness(db,a),c=comparableEffect(db,a,effect);
    return `<div class="analytics-grid equal-split">${panel('Did the same process improve?','Matched SKU, factory, line and overlapping inspection stages',bars([{label:'Before action',value:c.baseline.rate??0,note:c.baseline.rate===null?'No comparable baseline':`${c.baseline.defects}/${c.baseline.sample} · 95% interval ${pc(c.baseline.ci.low)}–${pc(c.baseline.ci.high)}`},{label:'After action',value:c.followup.rate??0,note:c.followup.rate===null?'No comparable follow-up':`${c.followup.defects}/${c.followup.sample} · 95% interval ${pc(c.followup.ci.low)}–${pc(c.followup.ci.high)}`}])+`<p class="chart-note">${c.conclusive?'Intervals do not overlap: stronger evidence of observed reduction.':'Intervals overlap or evidence is missing: improvement is not statistically established.'} Style matching is a proxy for complexity, not a causal adjustment.</p>`)}${panel('Verification horizon','Checks mature after the evidenced corrective action',`<div class="verification-horizon">${Object.entries(effect.checks).map(([key,v])=>`<div><b>${key.slice(1)}<small>days</small></b><span>${e(v.due||'Await implementation')}<small>${e(v.evidence||'Evidence required')}</small></span>${pill(v.valid?'Verified':'Pending',v.valid?'success':'warning')}</div>`).join('')}</div>`)}</div>`;
  }
  return '';
}
export function dataPage(db,a,manifest,selectedFixture){
  const p=profileData(db);
  return `<div class="page-head"><div><div class="eyebrow">DATA & TRUST</div><h1>Know what your data can support.</h1><p>Import operational records, inspect coverage, and retain a portable workspace.</p></div></div><div class="stat-grid">${stat('Production batches',n(db.batches.length),'Unique normalized batch IDs')}${stat('Inspection records',n(db.inspections.length),'Required for analysis')}${stat('Assumed thresholds',n(p.assumed),'Screening rules need review','warning')}${stat('Potential duplicate observations',n(p.duplicates.length),'Same batch, date, stage, defect and quantities')}</div>`+
    `<div class="analytics-grid equal-split">${panel('Import a dataset','JSON up to 50 MB · CSV / TSV / Excel up to 20 MB combined',`<div class="import-zone"><span>${icon('data')}</span><h3>Bring your production evidence together</h3><p>One inspection table or related sheets for batches, shipments, complaints, costs and actions.</p><button class="btn primary" data-action="upload">Choose files</button><a class="text-button" href="./test-files/inspection-template.csv" download>Download CSV template</a></div><p class="chart-note">A valid upload replaces the active dataset. Download a workspace snapshot to preserve edits before switching. Processing and storage stay in this browser origin.</p>`)}${panel('Active source',db.sourceName,`<dl class="source-details"><dt>Loaded</dt><dd>${e(new Date(db.loadedAt).toLocaleString('en-GB',{timeZone:'Asia/Dhaka'}))}</dd><dt>Inspection coverage</dt><dd>${e(p.dates.join(' → '))}</dd><dt>Supplied warnings</dt><dd>${a.warnings.length}</dd><dt>Storage</dt><dd>IndexedDB with local-storage fallback</dd></dl><div class="row"><button class="btn" data-action="snapshot">Download workspace JSON</button><button class="btn" data-action="report-json">Download analytical JSON</button><button class="btn" data-action="report-csv">Export CSV</button></div><p class="chart-note">Localhost and GitHub Pages have separate browser storage. Export and import a workspace to transfer it.</p>`)}</div>`+
    panel('Data completeness by decision input','Missing data stays unavailable; no demo values are substituted',bars(p.coverage.filter(c=>c.percent!==null).map(c=>({label:c.label,value:c.percent,note:`${c.known}/${c.total} records supplied`}))))+
    evidencePanel(db)+panel('Validation findings','Review these limitations before making a release decision',`<ul class="findings">${[...a.warnings,...(p.duplicates.length?['Potential duplicate observations: '+p.duplicates.join(', ')]:[])].map(w=>`<li>${e(w)}</li>`).join('')||'<li>No normalization warnings. Confirm source accuracy with the record owner.</li>'}</ul>`)+
    panel('Scenario library','20 known-answer synthetic cases plus an extended operations demonstration; loading replaces active data',`<button class="btn" data-action="enterprise-demo">Load multi-factory demonstration</button><p class="chart-note">Illustrative data · 54 batches · 58 inspection records · 4 factories · historical and current signals.</p><div class="scenario-controls"><label class="field"><span>Scenario</span><select id="fixture-select"><option value="">Choose a case</option>${manifest.map(m=>`<option value="${e(m.file)}" ${m.file===selectedFixture?'selected':''}>${e(m.title)}</option>`).join('')}</select></label><button class="btn primary" data-action="load-fixture" ${selectedFixture?'':'disabled'}>Load case</button><a class="btn" href="./test-files/scenarios.zip" download>Download all 20</a></div>`)+
    panel('Metric definitions & interpretation','Consistent denominators across screens and reports',table(['Measure','Definition / guardrail'],[['Defective unit rate','Defective units / inspected units × 100, by defect. Repeated inspections are observations, not distinct garments.'],['Strict COPQ','Internal + external failure cost. Prevention and appraisal belong to total cost of quality.'],['Expected avoided loss','Failure cost × recurrence probability × expected reduction for one comparable future incident.'],['Statistical limits','Exploratory p-chart: pooled defective proportion ± 3√(p(1−p)/n). Limits vary with sample size.'],['Exposure','Confirmed = failure evidence or reviewed complaint; precautionary = meaningful link or screening signal. Shared input never alone confirms failure.'],['Recovery completion','Sequential task capacity, reinspection, packing, material and approval lead time; 5/6/7-day calendar. No live shop-floor reservation.'],['Closure','Containment, cause review, owned actions, dependencies, approval evidence, independent review and 30/60/90-day checks.']].map(r=>r.map(e))))+`<p class="chart-note">Statistical method reference: <a href="https://www.itl.nist.gov/div898/software/dataplot/refman1/ch2/pcontrol.pdf" target="_blank" rel="noopener">NIST p-chart reference</a>. Sparse data and non-independent samples require specialist review.</p>`;
}
export function customersPage(db){
  const categories=new Map();for(const c of db.complaints)categories.set(c.category||'Unclassified',(categories.get(c.category||'Unclassified')||0)+1);
  return `<div class="page-head"><div><div class="eyebrow">VOICE OF THE CUSTOMER</div><h1>Connect customer failures to factory action.</h1><p>Review language signals, trace shipments, and preserve human classification decisions.</p></div></div><div class="stat-grid">${stat('Complaint records',n(db.complaints.length),'Records, not distinct affected garments')}${stat('Pending review',n(db.complaints.filter(c=>c.decision==='Pending review').length),'Requires human classification')}${stat('Unlinked complaints',n(db.complaints.filter(c=>!db.batches.some(b=>b.id===c.batch)).length),'No matching batch identifier','warning')}${stat('Known claim cost',db.complaints.some(c=>c.cost!==null)?usd(sum(db.complaints,'cost')):'—','Supplied claim costs only')}</div>`+panel('Customer failure mix','Number of complaint records by reviewed or supplied category',bars([...categories].map(([label,value])=>({label,value})),n))+panel('Feedback review queue','Rule-based suggestions require human approval; rejected classifications do not confirm exposure',table(['Complaint / customer','Failure description','Trace','Proposed classification','Human review'],db.complaints.map(c=>[e(c.id)+'<small class="cell-detail">'+e(c.customer)+' · '+e(c.date)+'</small>',e(c.text),`<button class="text-button" data-view="trace" data-batch="${e(c.batch)}" ${!db.batches.some(b=>b.id===c.batch)?'disabled':''}>${e(c.batch||'Unlinked')} ↗</button><small class="cell-detail">${e(db.shipments.filter(s=>s.batch===c.batch).map(s=>s.id).join(', ')||'Shipment not supplied')}</small>`,e(suggestClassification(c.text).join(' / ')||'No confident rule match')+`<small class="cell-detail">Current: ${e(c.category||'Unclassified')}</small>`,`<form id="feedback-${e(c.id)}" data-feedback="${e(c.id)}" class="inline-form"><input aria-label="Category for ${e(c.id)}" name="category" value="${e(c.category)}" required><select name="decision" aria-label="Decision for ${e(c.id)}">${['Pending review','Human reviewed','Rejected classification'].map(v=>`<option ${v===c.decision?'selected':''}>${v}</option>`).join('')}</select><input name="reviewer" placeholder="Reviewer" aria-label="Reviewer for ${e(c.id)}" value="${e(c.reviewer||'')}" required><input name="reviewEvidence" placeholder="Evidence reference" aria-label="Evidence for ${e(c.id)}" value="${e(c.reviewEvidence||'')}" required><button class="btn">Save review</button></form>`])))+(db.complaints.length?'':empty('No complaint records supplied. Import a Complaints sheet alongside inspections.'));
}
export function containmentPage(db,a,plans){
  const records=db.workspace?.containment||[],scope=[...a.confirmed,...a.precautionary],stock=scope.every(b=>b.inventory!==null)?sum(scope,'inventory'):null;
  return `<div class="page-head"><div><div class="eyebrow">IMMEDIATE RESPONSE</div><h1>Contain the exposure. Preserve the evidence.</h1><p>Record operational commitments while the investigation is still open.</p></div></div><div class="stat-grid">${stat('Confirmed batches',a.confirmed.length,'Direct quality evidence','danger')}${stat('Precautionary batches',a.precautionary.length,'Related, not declared defective','warning')}${stat('Stock to assess',n(stock),'Confirmed + precautionary units')}${stat('Recorded commitments',records.length,records.filter(r=>r.status==='Complete').length+' complete')}</div>`+panel('Containment register','Records track commitments; factory shipment blocks must be executed in operational systems',table(['Action','Batch scope','Owner / deadline','State','Evidence'],records.map(r=>[e(r.action),e(r.batches),e(r.owner)+'<small class="cell-detail">'+e(r.due)+'</small>',pill(r.status,r.status==='Complete'?'success':'warning'),e(r.evidence||'Pending')]))+`<form id="containment-form" class="form-grid three">${select('Action','action',['Stop production','Hold work in progress','Quarantine stock','Block shipment','100% inspection','Sample related batches','Separate material lots','Warehouse reinspection','Notify cross-functional team','Reserve rework capacity'],'Quarantine stock')}${field('Batch IDs (comma separated)','batches',scope.map(b=>b.id).join(', '),'text','required')}${field('Owner','owner','','text','required')}${field('Deadline','due',day(),'date','required')}${select('State','status',['Planned','In progress','Complete'],'Planned')}${field('Evidence reference','evidence','')}<button class="btn primary">Record containment</button></form>`)+panel('Update a containment commitment','Record progress and completion evidence',records.length?`<form id="containment-update-form" class="form-grid">${select('Commitment ID','id',records.map(r=>r.id),records[0].id)}${select('Status','status',['Planned','In progress','Complete'],'In progress')}${field('Evidence reference','evidence','')}<button class="btn primary">Update commitment</button></form>`:empty('Record a commitment first.'))+panel('Inspection capacity & commercial consequences','Scenario-derived estimates; detailed assumptions in Recovery planner',plans.length?table(['Strategy','Units to inspect','Inspector hours','Completion','Units before cut-off','Holding cost','Handling risk units'],plans.map(p=>[e(p.name),n(p.inspectUnits),n(p.inspectionHours),e(p.complete),n(p.unitsBeforeCutoff),usd(p.costs.holding),n(p.handlingUnits)])):empty('Supply complete confirmed and precautionary inventory to estimate inspection capacity.'));
}

function operatingPanels(db,a){
  const m=operatingMetrics(db,a),factory=groupRates(db,a.focusRows,'factory'),style=groupRates(db,a.focusRows,'sku');
  const heat=table(['Line / operation',...m.operations],m.lines.map(line=>[e(line),...m.operations.map(operation=>{const c=m.cells.find(c=>c.line===line&&c.operation===operation);return c?`<div class="heat-cell" style="background:rgba(153,80,67,${Math.min(.35,.04+c.rate/25)})"><b>${pc(c.rate)}</b><small>${c.defects}/${c.sample} · ${n(c.severityPoints)} severity points / 100</small><span title="${e(c.records.join(', '))}">${c.records.length} records</span></div>`:'<span class="muted">No sample</span>'})]));
  return panel('Locate the process concentration','Selected defect · each cell shows the observed rate and sample denominator',heat+'<p class="chart-note">Severity points use transparent weights: Minor/unknown = 1, Major/High = 3, Critical = 9. This prioritization score is not a defect probability. Hover record counts for evidence IDs.</p>')+
    `<div class="analytics-grid equal-split">${panel('Factory comparison','Volume-adjusted rate for the selected defect; product mix may differ',bars(factory.map(g=>({label:g.label,value:g.rate,note:g.defects+'/'+g.sample+' inspected'}))))}${panel('Style comparison','Compare complexity and inspection stages before attributing performance',bars(style.map(g=>({label:g.label,value:g.rate,note:g.defects+'/'+g.sample+' inspected'}))))}</div>`+
    panel('New and changing observations','Latest date compared with earlier dated observations',`<div class="stat-grid compact">${stat('Latest observed rate',pc(m.latestRate),m.latestDate||'No dated observations')}${stat('Earlier observed rate',pc(m.priorRate),'All earlier dates, same defect')}${stat('Change',m.latestRate!==null&&m.priorRate!==null?n(m.latestRate-m.priorRate)+' pp':'—','Descriptive change; verify comparability')}${stat('First-seen categories',new Set(m.newTypes.map(x=>x.type)).size,'First seen in this file, not globally new')}</div><p class="chart-note">${e(m.newTypes.map(x=>x.type+' ('+x.record+')').join(' · ')||'No first-seen categories on the latest focus date.')}</p>`);
}

function costLedgerPanel(db){
  const entries=db.workspace?.costLedger||[];
  return panel('Attributed cost ledger','Compare order, defect, factory and supplier costs using explicit attribution',`<details><summary>${entries.length} attributed entries · inspect or record a cost</summary>${entries.length?['order','defect','factory','supplier'].map(f=>`<h3>By ${f}</h3>`+table([f,'Total quality cost','Strict COPQ','Entries'],ledgerSummary(db,f).map(r=>[e(r.label),usd(r.qualityCost),usd(r.copq),r.records]))).join(''):empty('No attributed costs supplied. Aggregate totals cannot support reliable order or supplier comparisons.')}<p class="chart-note">Ledger categories fill missing aggregate cost inputs. Explicit aggregate inputs take precedence, so entries are never added twice. Clear a category in the cost form to use its ledger total.</p><form id="ledger-form" class="form-grid three">${select('Category','category',['prevention','appraisal','internal','external'],'internal')}${field('Amount USD','amount','','number','min="0" step="any" required')}${field('Description / source','description','','text','required')}${field('Order ID','order','')}${field('Defect category','defect','')}${field('Factory ID','factory','')}${field('Supplier','supplier','')}<button class="btn primary">Record attributed cost</button></form></details>`);
}

function evidencePanel(db){
  const records=db.workspace?.evidenceFiles||[];
  return panel('Evidence attachments','Local image and PDF evidence · 2 MB per file · 20 MB combined',`<div class="form-grid three"><label class="field"><span>Linked record ID</span><input id="evidence-link" list="evidence-records" placeholder="Inspection, action or incident ID" required><datalist id="evidence-records">${[db.incident.id,...db.inspections.map(i=>i.id),...db.actions.map(i=>i.id),...db.complaints.map(i=>i.id)].map(id=>`<option value="${e(id)}">`).join('')}</datalist></label><label class="field"><span>Evidence reviewer</span><input id="evidence-reviewer" placeholder="Responsible reviewer" required></label><button class="btn" data-action="attach-evidence">Attach image or PDF</button></div>${records.length?table(['Evidence ID','File / linked record','Reviewer','Attachment'],records.map(r=>[e(r.id),e(r.name)+'<small class="cell-detail">'+e(r.recordId)+'</small>',e(r.reviewer),`<a class="text-button" href="${e(r.dataUrl)}" download="${e(r.name)}">Download evidence</a>`])):empty('No binary evidence attached. Existing evidence references remain available in the inspection and action records.')}<p class="chart-note">Attachments travel with the workspace JSON snapshot. They are stored in this browser, not uploaded to a server. Attaching a file does not approve its linked record.</p>`);
}
